import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"CoreLib 动作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/level/corelib-actions.md","filePath":"modules/level/corelib-actions.md","lastUpdated":0}`),a={name:`modules/level/corelib-actions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="corelib-动作" tabindex="-1">CoreLib 动作 <a class="header-anchor" href="#corelib-动作" aria-label="Permalink to “CoreLib 动作”">​</a></h1><p>EmakiLevel 启用后会向 CoreLib 动作注册表追加等级与经验操作段。它们可用于其他模块的动作列表，例如烹饪完成、锻造结果、强化阶段、技能奖励或 CoreLib 管道模板。</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>本页只记录 EmakiLevel 注册的段；CoreLib 自带通用段见 <a href="./../corelib/actions.html">CoreLib 动作系统</a>。当前段 ID 只使用下表中的规范名，不再提供历史别名入口。旧的 <code>emakileveladdexp</code> 现在写作 <code>level_add_exp</code>，其余同理；旧的 <code>emakilevellevelup</code> 现在写作 <code>level_up</code>。</p></div><h2 id="段-id" tabindex="-1">段 ID <a class="header-anchor" href="#段-id" aria-label="Permalink to “段 ID”">​</a></h2><p>八个段的目标要求都是 <code>REQUIRED_ENTITY</code>，非玩家目标会跳过。</p><table tabindex="0"><thead><tr><th>段 ID</th><th>操作</th><th>是否使用 <code>amount</code></th></tr></thead><tbody><tr><td><code>level_add_exp</code></td><td>增加经验</td><td>是</td></tr><tr><td><code>level_set_exp</code></td><td>设置经验</td><td>是</td></tr><tr><td><code>level_remove_exp</code></td><td>扣除经验</td><td>是</td></tr><tr><td><code>level_add_level</code></td><td>增加等级</td><td>是</td></tr><tr><td><code>level_set_level</code></td><td>设置等级</td><td>是</td></tr><tr><td><code>level_remove_level</code></td><td>扣除等级</td><td>是</td></tr><tr><td><code>level_reset</code></td><td>重置指定等级类型</td><td>否</td></tr><tr><td><code>level_up</code></td><td>手动升级指定等级类型</td><td>否</td></tr></tbody></table><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to “参数”">​</a></h2><p>八个段都接受以下参数：</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>type</code></td><td>STRING</td><td>是</td><td>—</td><td>等级类型 ID，例如 <code>main</code>、<code>combat</code>、<code>mining</code>。</td></tr><tr><td><code>amount</code></td><td>EXPRESSION</td><td>否</td><td><code>0</code></td><td>经验或等级数量。支持纯数字，也可写 CoreLib 表达式。等级操作会四舍五入为整数。</td></tr><tr><td><code>reason</code></td><td>STRING</td><td>否</td><td><code>action</code></td><td>操作原因，会进入等级服务的原因字段。</td></tr></tbody></table><p><code>level_add_exp</code> 额外接受两个参数：</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>auto_upgrade</code></td><td>BOOLEAN</td><td>否</td><td><code>true</code></td><td>跨过阈值时是否自动升级。</td></tr><tr><td><code>silent</code></td><td>BOOLEAN</td><td>否</td><td><code>false</code></td><td>是否抑制升级反馈。</td></tr></tbody></table><p><code>level_reset</code> 与 <code>level_up</code> 会忽略 <code>amount</code> 的值，但仍然声明了这个参数，所以配置里写上它不会被当成未知参数报错。<code>auto_upgrade</code> 与 <code>silent</code> 只在 <code>level_add_exp</code> 上声明，写在其他段上会在加载期报未知参数。</p><p>「作用于谁」由 source 决定，不再有 <code>target</code> 参数：作用于执行者自己写 <code>self</code>，指定玩家用 <code>player_by_name</code>。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 给自己增加 50 点主等级经验</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | level_add_exp type=main amount=50 reason=forge_reward&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 给自己增加 1 级战斗等级</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | level_add_level type=combat amount=1 reason=boss_reward&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 增加经验但不自动升级、不提示</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | level_add_exp type=main amount=10 auto_upgrade=false silent=true&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 给指定玩家设置挖矿经验</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | level_set_exp type=mining amount=200 reason=admin_adjust&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 重置主等级类型</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | level_reset type=main reason=admin_reset&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 按等级系统执行一次手动升级</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=PlayerName | level_up type=main&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # amount 写成表达式</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | level_add_exp type=main amount=%var.base%*2+10&#39;</span></span></code></pre></div><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li><code>amount</code> 声明为 EXPRESSION，参数文本里的占位符会先被渲染再交给表达式引擎求值，所以 <code>%var.*%</code>、模块写入的上下文占位符与 PlaceholderAPI 占位符都能直接参与运算。</li><li>等级操作（<code>level_add_level</code>、<code>level_set_level</code>、<code>level_remove_level</code>）会把 <code>amount</code> 四舍五入为整数。</li><li>等级服务拒绝这次操作时，该段以 <code>REJECTED</code> 失败，并在结果里带上服务给出的原因。</li><li>成功时会输出 <code>type</code>、<code>old_level</code>、<code>new_level</code>、<code>old_exp</code>、<code>new_exp</code>、<code>amount</code>，可在 debug 输出里查看改动前后的状态。</li></ul>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};